import PDFDocument from 'pdfkit';
import { Readable } from 'stream';
import path from 'path';

interface InvoiceItem {
    product: {
        englishName: string;
        malayalamName: string;
        preparation: string;
    };
    quantity: number;
    price: number;
    lineTotal: number;
}

interface InvoiceData {
    invoiceNumber: string;
    orderDate: Date;
    customer: {
        name: string;
        companyName: string;
        address: string;
        phone: string;
    };
    items: InvoiceItem[];
    subtotal: number;
    totalWeight: number;
    tier: string;
}

export async function generateInvoicePDF(data: InvoiceData): Promise<Buffer> {
    return new Promise((resolve, reject) => {
        try {
            // Use courier font which is standard and doesn't require external files
            const doc = new PDFDocument({ 
                size: 'A4', 
                margin: 50,
                bufferPages: true,
                autoFirstPage: true
            });
            const chunks: Buffer[] = [];

        // Collect PDF chunks
        doc.on('data', (chunk) => chunks.push(chunk));
        doc.on('end', () => resolve(Buffer.concat(chunks)));
        doc.on('error', reject);

        const formatCurrency = (amount: number) => 
            new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'GBP' }).format(amount);

        // Header - Company Info
        doc.fontSize(24).text('Kerala Fresh Fish', 50, 50);
        doc.fontSize(10).text('Premium Wholesale Seafood Supplier', 50, 80);
        
        // Invoice Title
        doc.fontSize(20).text('PRO-FORMA INVOICE', 400, 50, { align: 'right' });
        doc.fontSize(10).text(`Invoice #: ${data.invoiceNumber}`, 400, 75, { align: 'right' });
        doc.text(`Date: ${data.orderDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}`, 400, 90, { align: 'right' });

        // Line separator
        doc.moveTo(50, 120).lineTo(545, 120).stroke();

        // Bill To Section
        doc.fontSize(12).text('BILL TO:', 50, 140);
        doc.fontSize(10).text(data.customer.companyName, 50, 160);
        doc.text(data.customer.name, 50, 175);
        const addressLines = data.customer.address.split('\n');
        let yPos = 190;
        addressLines.forEach(line => {
            doc.text(line, 50, yPos);
            yPos += 15;
        });
        doc.text(`Phone: ${data.customer.phone}`, 50, yPos);

        // Order Summary Box
        const summaryStartY = 140;
        doc.fontSize(10);
        doc.text('ORDER SUMMARY', 350, summaryStartY);
        doc.text(`Total Weight:`, 350, summaryStartY + 20);
        doc.text(`${data.totalWeight.toFixed(2)} kg`, 480, summaryStartY + 20, { align: 'right' });
        doc.text(`Pricing Tier:`, 350, summaryStartY + 35);
        doc.text(data.tier, 480, summaryStartY + 35, { align: 'right' });

        // Items Table
        const tableTop = 280;
        doc.fontSize(10);
        
        // Table Header
        doc.rect(50, tableTop, 495, 25).fillAndStroke('#2196F3', '#2196F3');
        doc.fillColor('#FFFFFF');
        doc.text('PRODUCT', 60, tableTop + 8);
        doc.text('QTY (kg)', 280, tableTop + 8, { width: 70, align: 'center' });
        doc.text('PRICE/KG', 360, tableTop + 8, { width: 80, align: 'right' });
        doc.text('TOTAL', 450, tableTop + 8, { width: 85, align: 'right' });

        // Table Rows
        let yPosition = tableTop + 35;
        doc.fillColor('#000000');

        data.items.forEach((item, index) => {
            // Alternate row colors
            if (index % 2 === 0) {
                doc.rect(50, yPosition - 5, 495, 45).fill('#F5F5F5');
            }

            doc.fillColor('#000000');
            doc.fontSize(10).text(item.product.englishName, 60, yPosition, { width: 200 });
            doc.fontSize(9).fillColor('#616161').text(`${item.product.malayalamName} • ${item.product.preparation}`, 60, yPosition + 13, { width: 200 });
            
            doc.fillColor('#000000').fontSize(10);
            doc.text(`${item.quantity}`, 280, yPosition + 5, { width: 70, align: 'center' });
            doc.text(formatCurrency(item.price), 360, yPosition + 5, { width: 80, align: 'right' });
            doc.text(formatCurrency(item.lineTotal), 450, yPosition + 5, { width: 85, align: 'right' });

            yPosition += 45;
        });

        // Total Section
        yPosition += 10;
        doc.rect(50, yPosition, 495, 35).fill('#FAFAFA');
        doc.fillColor('#000000').fontSize(14);
        doc.text('TOTAL AMOUNT:', 350, yPosition + 10);
        doc.fontSize(16).fillColor('#2196F3').text(formatCurrency(data.subtotal), 450, yPosition + 8, { width: 85, align: 'right' });

        // Payment Terms
        yPosition += 60;
        doc.fillColor('#000000').fontSize(11).text('PAYMENT TERMS', 50, yPosition);
        doc.fontSize(9).fillColor('#424242');
        doc.text('• This is a pro-forma invoice for order confirmation', 50, yPosition + 20);
        doc.text('• Final invoice will be sent after shipment', 50, yPosition + 35);
        doc.text('• Payment due upon receipt of final invoice', 50, yPosition + 50);
        doc.text('• All prices are in GBP (£)', 50, yPosition + 65);

        // Footer
        const footerY = 750;
        doc.moveTo(50, footerY).lineTo(545, footerY).stroke();
        doc.fontSize(9).fillColor('#757575').text('Kerala Fresh Fish | Premium Wholesale Seafood Supplier', 50, footerY + 10, { align: 'center', width: 495 });
        doc.text('Thank you for your business!', 50, footerY + 25, { align: 'center', width: 495 });

        // Finalize PDF
        doc.end();
        } catch (error) {
            reject(error);
        }
    });
}

export function generateInvoiceNumber(): string {
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const random = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
    return `INV-${year}${month}${day}-${random}`;
}
